const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');
async function main() {
  // retry after Transient: one debit, same receipt forwarded
  let ledger = new Ledger(); const seen = []; let calls = 0;
  let svc = new PaymentService(ledger, { acknowledge: async r => { seen.push(r); if (++calls < 3) throw new Transient('t'); } });
  const r = await svc.pay('a', 'k', 5);
  assert.equal(ledger.entries.length, 1); assert.equal(seen.length, 3);
  assert(seen.every(x => x === r));
  // repeat returns original; conflict does not debit
  assert.equal(await svc.pay('a', 'k', 5), r);
  await assert.rejects(svc.pay('a', 'k', 6), /key conflict/);
  assert.equal(ledger.entries.length, 1);
  // tenant scoping
  await svc.pay('b', 'k', 6); assert.equal(ledger.entries.length, 2);
  // concurrency
  ledger = new Ledger(); svc = new PaymentService(ledger, { acknowledge: async () => {} });
  const rs = await Promise.all([svc.pay('a', 'c', 1), svc.pay('a', 'c', 1), svc.pay('a', 'c', 1)]);
  assert.equal(ledger.entries.length, 1); assert(rs.every(x => x === rs[0]));
  // exhausted: final exception preserved
  const errs = []; calls = 0;
  svc = new PaymentService(ledger, { acknowledge: async () => { const e = new Transient('n' + ++calls); errs.push(e); throw e; } });
  await assert.rejects(svc.pay('a', 'x', 1, 2), e => e === errs[1]); assert.equal(calls, 2);
  // non-transient not retried
  calls = 0; const boom = new Error('boom');
  svc = new PaymentService(ledger, { acknowledge: async () => { calls++; throw boom; } });
  await assert.rejects(svc.pay('a', 'y', 1), e => e === boom); assert.equal(calls, 1);
  // validation before any action
  ledger = new Ledger(); calls = 0;
  svc = new PaymentService(ledger, { acknowledge: async () => { calls++; } });
  for (const a of [['', 'k', 1], ['t', '', 1], ['t', 'k', 1.5], ['t', 'k', -1], ['t', 'k', 1, 0], ['t', 'k', 1, 6], ['t', 'k', 1, 1.5]])
    await assert.rejects(svc.pay(...a), /invalid payment/);
  assert.equal(ledger.entries.length, 0); assert.equal(calls, 0);
}
module.exports = main();

