export interface Receipt { id: number; tenant: string; key: string; cents: number }
export class Ledger {
  readonly entries: Receipt[] = [];
  // tenant -> key -> original receipt. Nested maps avoid delimiter collisions.
  private readonly byKey = new Map<string, Map<string, Receipt>>();

  async apply(tenant: string, key: string, cents: number): Promise<Receipt> {
    if (!tenant || !key || !Number.isInteger(cents) || cents <= 0) throw new Error('invalid payment');
    // Lookup and insert happen synchronously (no await in between), so concurrent
    // calls with the same tenant/key cannot both debit.
    let keys = this.byKey.get(tenant);
    if (!keys) { keys = new Map(); this.byKey.set(tenant, keys); }
    const existing = keys.get(key);
    if (existing) {
      if (existing.cents !== cents) throw new Error('key conflict');
      return existing;
    }
    const receipt = { id: this.entries.length + 1, tenant, key, cents };
    this.entries.push(receipt);
    keys.set(key, receipt);
    return receipt;
  }
}

